import{_ as a,o as t,c as o,a5 as c}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Plan — Leave Workspace (FR 3.4.16)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-16-leave-workspace/plan.md","filePath":"feature/agency-workspace/3-4-16-leave-workspace/plan.md"}'),n={name:"feature/agency-workspace/3-4-16-leave-workspace/plan.md"};function r(d,e,s,i,l,h){return t(),o("div",null,[...e[0]||(e[0]=[c(`<h1 id="plan-—-leave-workspace-fr-3-4-16" tabindex="-1">Plan — Leave Workspace (FR 3.4.16) <a class="header-anchor" href="#plan-—-leave-workspace-fr-3-4-16" aria-label="Permalink to &quot;Plan — Leave Workspace (FR 3.4.16)&quot;">​</a></h1><p>&gt; Liên kết: <a href="./spec.html">spec.md</a> — cho member tự rời 1 Workspace, vẫn còn trong Agency. API mới vừa code xong.</p><h2 id="_1-pham-vi-ky-thuat" tabindex="-1">1. Phạm vi kỹ thuật <a class="header-anchor" href="#_1-pham-vi-ky-thuat" aria-label="Permalink to &quot;1. Phạm vi kỹ thuật&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Repo</td><td><code>brandhub-business-service</code></td></tr><tr><td>File implement</td><td><code>WorkspaceServiceImpl.leaveWorkspace()</code>, <code>WorkspaceServiceImpl.assertNotLastManager()</code> (helper dùng chung)</td></tr><tr><td>File đã có</td><td><code>WorkspaceController</code> (<code>DELETE /{workspaceId}/leave</code>), <code>WorkspaceMemberRepository</code></td></tr></tbody></table><h2 id="_2-api-contract-final" tabindex="-1">2. API Contract (final) <a class="header-anchor" href="#_2-api-contract-final" aria-label="Permalink to &quot;2. API Contract (final)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DELETE /api/v1/workspaces/{workspaceId}/leave</span></span>
<span class="line"><span>Authorization: Bearer &lt;access-token&gt;</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;null&gt;</span></span></code></pre></div><p>Không có request body — <code>userId</code> lấy từ <code>AuthenticatedUser</code> principal (JWT). Không có <code>@RequireRole</code> — endpoint mở cho bất kỳ user đã đăng nhập nào, vì action chỉ tác động lên chính <code>WorkspaceMember</code> record của <code>currentUser</code>.</p><h2 id="_3-data-model" tabindex="-1">3. Data Model <a class="header-anchor" href="#_3-data-model" aria-label="Permalink to &quot;3. Data Model&quot;">​</a></h2><ul><li>Đọc <code>workspace_members</code> theo <code>workspaceId + userId(currentUser) + isActive=true</code>.</li><li>Ghi: <code>UPDATE workspace_members SET is_active = false, updated_at = ? WHERE id = ?</code> — soft-delete, <strong>không đụng <code>agency_members</code></strong>.</li><li>Không migration.</li></ul><h2 id="_4-luong-xu-ly" tabindex="-1">4. Luồng xử lý <a class="header-anchor" href="#_4-luong-xu-ly" aria-label="Permalink to &quot;4. Luồng xử lý&quot;">​</a></h2><ol><li><code>findByWorkspaceIdAndUserIdAndIsActiveTrue</code> — không tìm thấy → 403 <code>WORKSPACE_ACCESS_DENIED</code>.</li><li><code>assertNotLastManager(workspaceId, member)</code>: nếu <code>role != MANAGER</code> → pass; nếu <code>role == MANAGER</code> → đếm MANAGER active — <code>&lt;= 1</code> → 409 <code>LAST_MANAGER_CANNOT_BE_REMOVED</code>.</li><li>Set <code>isActive = false</code>, <code>updatedAt = now()</code>, save.</li></ol><h2 id="_5-dependencies" tabindex="-1">5. Dependencies <a class="header-anchor" href="#_5-dependencies" aria-label="Permalink to &quot;5. Dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chiều</th><th>Mô tả</th></tr></thead><tbody><tr><td>Chặn bởi</td><td><code>WorkspaceMember</code> entity + repository (đã có)</td></tr><tr><td>Bị chặn</td><td>Không — nhưng dùng chung <code>assertNotLastManager</code> với FR 3.4.20 (Update Role) và 3.4.21 (Remove Member)</td></tr></tbody></table><h2 id="_6-rui-ro-ky-thuat" tabindex="-1">6. Rủi ro kỹ thuật <a class="header-anchor" href="#_6-rui-ro-ky-thuat" aria-label="Permalink to &quot;6. Rủi ro kỹ thuật&quot;">​</a></h2><ul><li><strong>Guard <code>assertNotLastManager</code> dùng chung 3 FR (3.4.16/3.4.20/3.4.21)</strong> — sửa logic 1 chỗ ảnh hưởng cả 3, cần test cả 3 khi thay đổi threshold hay điều kiện đếm MANAGER.</li><li><strong>Không có <code>@RequireRole</code></strong> — rủi ro bảo mật thấp vì action luôn tự áp dụng lên <code>currentUser</code>, không nhận <code>memberId</code> tham số, nên không thể leave giùm người khác; nhưng cần review kỹ nếu sau này thêm tham số.</li><li><strong>FE đã build UI &quot;Leave workspace&quot;</strong> (xác nhận 2026-09-23: nút trong <code>InternalMembersSection.tsx</code> + <code>workspaceService.leaveWorkspace</code> + i18n <code>leaveButton</code>/<code>leaveSuccess</code>) — không còn là mục chờ xác nhận, xem task.md. Theo Out of Scope, chỉ &quot;tự động chọn MANAGER thay thế&quot; là ngoài phạm vi.</li></ul>`,15)])])}const g=a(n,[["render",r]]);export{u as __pageData,g as default};
